// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, address actor, address recipient) public {
        vm.assume(actor != address(c) && actor != address(0));
        vm.assume(recipient != address(c));
        amount = bound(amount, 1, type(uint256).max / 4);
        // contract holds zero balance at this point (fresh deploy, nothing funded)
        require(address(c).balance == 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.multiplicate{value: amount}(recipient) { ok = true; } catch { ok = false; }
        // RULE: with zero prior balance, any positive-value multiplicate must revert
        // (the >= condition fires and the 2*amount transfer exceeds the balance).
        assertTrue(!ok);
    }
}
